SELECT codProducto, codAlmacen, DATE(fecharegistro) INTO @p,@a,@f FROM detallefactura_venta ORDER BY codDetalleFacturaV DESC LIMIT 1;
SELECT codFacturaV INTO @fv FROM factura_venta ORDER BY codFacturaV DESC LIMIT 1;
SET @t=NOW(6); SELECT SQL_NO_CACHE MAX(codNotaSalida) INTO @x FROM notasalida WHERE documentoreferencia=@fv; SELECT 'max_notasalida_ms', TIMESTAMPDIFF(MICROSECOND,@t,NOW(6))/1000;
SET @t=NOW(6); SELECT SQL_NO_CACHE EXISTS(select * from movimientostock ms where ms.codProducto=@p and ms.codAlmacen=@a and ms.tipoStock=1) INTO @x; SELECT 'exists_movstock_ms', TIMESTAMPDIFF(MICROSECOND,@t,NOW(6))/1000;
SET @t=NOW(6); SELECT SQL_NO_CACHE ms.stockFinal INTO @x from movimientostock ms where ms.codProducto=@p and ms.codAlmacen=@a and ms.tipoStock=1 ORDER BY ms.fechaRegistro DESC,ms.codMovStock desc limit 1; SELECT 'last_movstock_ms', TIMESTAMPDIFF(MICROSECOND,@t,NOW(6))/1000;
SET @t=NOW(6);
SELECT SQL_NO_CACHE IFNULL(SUM(t.cantidad_final), 0) INTO @x FROM (SELECT DISTINCT dfv.codDetalleFacturaV, IF(dfv.unidadingresada <> p2.codUnidadMedida AND ue.factor IS NOT NULL, dfv.cantidad * ue.factor, dfv.cantidad) AS cantidad_final FROM detallefactura_venta dfv JOIN producto p2 ON p2.codProducto = dfv.codProducto LEFT JOIN (SELECT codProducto, codUnidadMedida, MAX(factor) AS factor FROM unidadequivalente WHERE compra_venta = 2 GROUP BY codProducto, codUnidadMedida) ue ON ue.codProducto = dfv.codProducto AND ue.codUnidadMedida = dfv.unidadingresada WHERE dfv.codProducto = @p AND dfv.codAlmacen = @a AND dfv.estado = 1 AND dfv.anulado = 0 AND dfv.fecharegistro >= @f AND dfv.fecharegistro < @f + INTERVAL 1 DAY) t;
SELECT 'venta_neta_bruto_ms', TIMESTAMPDIFF(MICROSECOND,@t,NOW(6))/1000;
SET @t=NOW(6);
SELECT SQL_NO_CACHE IFNULL(SUM(t_dev.cantidad_final), 0) INTO @x FROM (SELECT DISTINCT dnc.codDetalleNotaCredito, IF(dnc.unidadingresada <> p3.codUnidadMedida AND ue2.factor IS NOT NULL, dnc.cantidad * ue2.factor, dnc.cantidad) AS cantidad_final FROM factura_venta fv1 JOIN detallefactura_venta dfv2 ON dfv2.codFacturaV = fv1.codFacturaV AND dfv2.codProducto = @p AND dfv2.codAlmacen = @a JOIN notacredito nc ON nc.codNotaCredito = fv1.codNotaCredito JOIN detallenotacredito dnc ON dnc.codNotaCredito = nc.codNotaCredito AND dnc.codProducto = @p JOIN producto p3 ON p3.codProducto = dnc.codProducto LEFT JOIN (SELECT codProducto, codUnidadMedida, MAX(factor) AS factor FROM unidadequivalente WHERE compra_venta = 2 GROUP BY codProducto, codUnidadMedida) ue2 ON ue2.codProducto = dnc.codProducto AND ue2.codUnidadMedida = dnc.unidadingresada WHERE fv1.anulado = 0 AND fv1.fecharegistro >= @f AND fv1.fecharegistro < @f + INTERVAL 1 DAY) t_dev;
SELECT 'venta_neta_devol_ms', TIMESTAMPDIFF(MICROSECOND,@t,NOW(6))/1000;
SET @t=NOW(6); select SQL_NO_CACHE EXISTS(select * from req_almacen ra where ra.codPedidoVenta = 123 AND ra.estado != 12) INTO @x; SELECT 'req_almacen_ms', TIMESTAMPDIFF(MICROSECOND,@t,NOW(6))/1000;
